refentry.refsect1:
&reftitle.description;

 mixedcurl_getinfo
 CurlHandlehandle
 intnulloption&null;



 Ottiene informazioni sull'ultimo trasferimento.

  &reftitle.examples;



    Esempio di curl_getinfo


<?php
// Crea un gestore cURL
$ch = curl_init('http://www.example.com/');

// Esegue
curl_exec($ch);

// Controlla se si sono verificati degli errori
if (!curl_errno($ch)) {
  $info = curl_getinfo($ch);
  echo 'Ci sono voluti ', $info['total_time'], ' secondi per inviare una richiesta a ', $info['url'], "\n";
}
?>







    Esempio di curl_getinfo con il parametro option


<?php
// Crea un gestore cURL
$ch = curl_init('http://www.example.com/');

// Esegue
curl_exec($ch);

// Controlla il codice di stato HTTP
if (!curl_errno($ch)) {
  switch ($http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE)) {
    case 200:  # OK
      break;
    default:
      echo 'Codice HTTP inatteso: ', $http_code, "\n";
  }
}
?>
